import { readFileSync } from 'node:fs'
import { join } from 'node:path'
import { beforeEach, describe, expect, it } from 'vitest'
import { asUser, createTestDb, createUser, type TestDb } from './testDb'
import { SAMPLE_COURSES } from '@/configs/sampleCourses'

/*
 * supabase/seeds/sample_courses.sql (generated by `npm run db:sample-seed`): run against the real
 * migrations, it adds the four sample courses exactly as the in-app "Add a sample course" would.
 */

const SEED = readFileSync(join(__dirname, '..', '..', 'supabase', 'seeds', 'sample_courses.sql'), 'utf8')
const withOwner = (email: string) => SEED.replace(`v_owner_email text := '';`, `v_owner_email text := '${email}';`)

describe('sample courses seed', () => {
    let db: TestDb
    let admin: string

    beforeEach(async () => {
        db = await createTestDb()
        admin = await createUser(db, 'admin@school.test', 'admin')
    })

    it('adds every sample as a published course taught by the oldest administrator', async () => {
        await db.exec(SEED)

        const courses = await db.query<{ id: string; title: string; status: string; join_code: string }>(
            `select c.id, c.title, c.status, c.join_code from public.courses c
             join public.course_teachers t on t.course_id = c.id and t.teacher_id = $1 order by c.title`,
            [admin],
        )
        expect(courses.rows.map((c) => c.title).sort()).toEqual(SAMPLE_COURSES.map((s) => s.title).sort())
        expect(courses.rows.every((c) => c.status === 'published')).toBe(true)
        expect(courses.rows.map((c) => c.join_code).sort()).toEqual(['SMPBIO1', 'SMPEGYPT1', 'SMPMATH1', 'SMPSPACE1'])

        for (const sample of SAMPLE_COURSES) {
            const course = courses.rows.find((c) => c.title === sample.title)!
            const activities = await db.query<{ title: string; status: string; xp_ok: boolean; questions: number }>(
                `select a.title, a.status,
                        a.xp_reward = (select default_xp from public.xp_rules r
                                       where r.source = case a.kind when 'lesson' then 'lesson_completion'
                                                                    when 'quiz' then 'quiz_completion'
                                                                    else a.kind::text end::public.xp_source) as xp_ok,
                        (select count(*)::int from public.questions q where q.activity_id = a.id) as questions
                 from public.activities a where a.course_id = $1 order by a.position`,
                [course.id],
            )
            expect(activities.rows.map((a) => a.title)).toEqual(sample.activities.map((a) => a.title))
            expect(activities.rows.map((a) => a.questions)).toEqual(
                sample.activities.map((a) => a.questions?.length ?? 0),
            )
            expect(activities.rows.every((a) => a.status === 'published' && a.xp_ok)).toBe(true)
        }

        // Every choice question has a correct option stored in its (hidden) answer key
        const unkeyed = await db.query(
            `select q.id from public.questions q join public.question_keys k on k.question_id = q.id
             where q.kind <> 'short_answer' and cardinality(k.correct_option_ids) = 0`,
        )
        expect(unkeyed.rows).toHaveLength(0)
        const prerequisites = await db.query(`select 1 from public.activity_prerequisites`)
        expect(prerequisites.rows.length).toBeGreaterThan(0)
    })

    it('is safe to run twice', async () => {
        await db.exec(SEED)
        await db.exec(SEED)
        expect((await db.query(`select 1 from public.courses`)).rows).toHaveLength(SAMPLE_COURSES.length)
    })

    it('a student who joins sees the lessons and quizzes, but never the answer keys', async () => {
        await db.exec(SEED)
        const student = await createUser(db, 'ava@school.test')
        const course = (await db.query<{ id: string }>(`select id from public.courses where join_code = 'SMPBIO1'`))
            .rows[0]
        await db.query(`insert into public.course_enrollments (course_id, student_id) values ($1, $2)`, [
            course.id,
            student,
        ])

        await asUser(db, student, async () => {
            const visible = await db.query(`select 1 from public.activities where course_id = $1`, [course.id])
            expect(visible.rows).toHaveLength(
                SAMPLE_COURSES.find((s) => s.id === 'cells-photosynthesis')!.activities.length,
            )
            expect((await db.query(`select * from public.question_keys`)).rows).toHaveLength(0)
        })
    })

    it('can be owned by a named teacher, and refuses an unknown or student email', async () => {
        const teacher = await createUser(db, 'Teacher@School.test', 'teacher')
        await db.exec(withOwner('teacher@school.test'))
        const taught = await db.query(`select 1 from public.course_teachers where teacher_id = $1`, [teacher])
        expect(taught.rows).toHaveLength(SAMPLE_COURSES.length)

        await createUser(db, 'kid@school.test')
        await expect(db.exec(withOwner('kid@school.test'))).rejects.toThrow(/No teacher or administrator/)
    })

    it('needs an administrator when no owner email is given', async () => {
        const empty = await createTestDb()
        await expect(empty.exec(SEED)).rejects.toThrow(/no administrator account/)
    })
})
